(()=>{'use strict';
const MODE_KEY='abc-roofing-governance-mode-v1',stages=['LEADS','APPOINTMENTS','INSPECTIONS','SCOPES','APPROVALS','PRODUCTION_READY','PRODUCTION','QC','CLOSEOUT'];let govMode=localStorage.getItem(MODE_KEY)==='ON'?'ON':'OFF',ledger,forward,annual,govFeed,govResults={},cycleQualification,currentBranch=null,selectedJob=null;const $=x=>document.getElementById(x),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),count=(a,f)=>a.filter(f).length,active=()=>ledger.jobs.filter(j=>j.status==='ACTIVE'),completed=()=>ledger.jobs.filter(j=>j.status==='COMPLETED'),branchJobs=b=>active().filter(j=>j.branch===b),bad=j=>j.governance!=='ESTABLISHED';
function applyMode(){document.body.classList.toggle('gov-on',govMode==='ON');$('govToggle').textContent='Governance: '+govMode;$('govToggle').setAttribute('aria-pressed',govMode==='ON'?'true':'false')}
function renderBridge(){let a=active(),done=completed(),scheduled=a.filter(j=>j.scheduled),issues=govMode==='ON'?a.filter(j=>govResults[j.id]&&govResults[j.id].qualifiedState!=='ESTABLISHED'):[],metric=govMode==='ON'?[['Completed',done.length],['Active',a.length],['Scheduled next',scheduled.length],['Need attention',issues.length]]:[['Completed',done.length],['Active',a.length],['Scheduled next',scheduled.length],['Month-end workload',a.length]];$('metrics').innerHTML=metric.map(x=>'<div class="metric"><span class="muted">'+x[0]+'</span><b>'+x[1]+'</b></div>').join('');
 $('branches').innerHTML=['Tampa','Orlando','Jacksonville'].map(b=>{let j=branchJobs(b),d=done.filter(x=>x.branch===b),s=j.filter(x=>x.scheduled),f=j.filter(x=>govResults[x.id]&&govResults[x.id].qualifiedState!=='ESTABLISHED');return '<button class="branchCard" data-branch="'+b+'"><strong>'+b+'</strong><div class="branchStats"><span>'+d.length+' completed</span><span>'+j.length+' active</span><span>'+s.length+' scheduled</span>'+(govMode==='ON'?'<span>'+f.length+' governance flags</span>':'')+'</div></button>'}).join('');document.querySelectorAll('[data-branch]').forEach(b=>b.onclick=()=>openBranch(b.dataset.branch));
 $('flags').innerHTML=govMode==='ON'?issues.sort((x,y)=>(x.priority==='CRITICAL'?-2:-1)-(y.priority==='CRITICAL'?-2:-1)).map(j=>'<div class="flag"><div><b>'+esc(j.id)+' · '+esc(j.branch)+'</b><span class="muted">'+esc((govResults[j.id]?.findings||[])[0]||j.flag||govResults[j.id]?.qualifiedState||'Requires review')+'</span></div><span class="'+(govResults[j.id]?.qualifiedState||'UNPROVEN')+'">'+(govResults[j.id]?.label||'Requires review')+'</span></div>').join(''):'<p class="muted">Governance is off. CRM and Agile operating state remain visible; evidence qualification and governance-derived exceptions are not applied.</p>';
 $('forward').innerHTML=[['September carryover',forward.carryoverJobIds.length],['Committed scheduled',forward.committedScheduled.length],['Modeled new intake',forward.modeledNewIntake],['Modeled completion capacity',forward.modeledCompletionCapacity]].map(x=>'<div class="metric"><span class="muted">'+x[0]+'</span><b>'+x[1]+'</b></div>').join('');
 if(govMode==='ON'&&cycleQualification){$('forward').insertAdjacentHTML('afterend','<div id="cycleGov" class="panel" style="margin-top:12px"><div class="eyebrow">Agile cycle qualification</div><h2>CRM reports '+cycleQualification.reportedCompletionPercent+'% complete · Governance establishes '+cycleQualification.governanceQualifiedCompletionPercent+'%</h2><p class="muted">Same cycle, independently qualified from supplied evidence.</p></div>')}else document.getElementById('cycleGov')?.remove();$('annual').innerHTML=annual.months.map(m=>'<div class="stage"><b>'+m.completed+'</b><span>'+m.month+' completed</span>'+(govMode==='ON'?'<div class="'+(m.monthEndIssues?'HIGH':'ESTABLISHED')+'" style="font-size:.65rem;margin-top:5px">'+m.monthEndIssues+' issues · '+m.averageCycleDays+'d cycle</div>':'<div class="muted" style="font-size:.65rem;margin-top:5px">'+m.opened+' opened</div>')+'</div>').join('');
}
function openBranch(b){currentBranch=b;selectedJob=null;$('branchTitle').textContent=b+' Branch · September month-end';$('overlay').classList.add('open');showFront();renderBranch()}
function renderBranch(){let a=branchJobs(currentBranch),done=completed().filter(j=>j.branch===currentBranch);$('workflow').innerHTML=stages.map(s=>'<div class="stage"><b>'+count(a,j=>j.stage===s)+'</b><span>'+s.replaceAll('_',' ')+'</span></div>').join('');let rows=[...a,...done.slice(-4)];$('jobs').innerHTML=rows.map(j=>'<article class="job"><div class="eyebrow">'+(j.status==='COMPLETED'?'Completed · '+esc(j.completedOn):esc(j.stage.replaceAll('_',' ')))+'</div><h3>'+esc(j.id)+'</h3><p class="muted">'+esc(j.customer)+'</p>'+(j.status==='ACTIVE'&&j.scheduled?'<p class="muted">Scheduled: '+esc(j.scheduledStart)+'</p>':'')+(govMode==='ON'&&j.status==='ACTIVE'&&govResults[j.id]?'<p class="'+govResults[j.id].qualifiedState+'"><b>'+esc(govResults[j.id].label)+'</b></p>'+(govResults[j.id].findings.length?'<p>'+esc(govResults[j.id].findings[0])+'</p>':''):'')+(j.status==='ACTIVE'?'<button class="btn" data-select="'+j.id+'">Select for action</button> ':'')+'<a href="./crm.html?job='+encodeURIComponent(j.id)+'">Open CRM record →</a></article>').join('');document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selectedJob=ledger.jobs.find(j=>j.id===b.dataset.select);showBack()})}
function showFront(){$('front').classList.add('active');$('back').classList.remove('active');$('flip').textContent='Flip to actions'}function showBack(){$('front').classList.remove('active');$('back').classList.add('active');$('flip').textContent='Flip to operations';$('receipt').innerHTML=selectedJob?'<b>Selected:</b> '+esc(selectedJob.id)+' · '+esc(selectedJob.flag||selectedJob.stage)+'<br>Choose a governed action.':'No job selected. Return to operations and select an active job.'}
$('govToggle').onclick=()=>{govMode=govMode==='ON'?'OFF':'ON';localStorage.setItem(MODE_KEY,govMode);applyMode();renderBridge();if(currentBranch)renderBranch()};$('flip').onclick=()=> $('front').classList.contains('active')?showBack():showFront();$('close').onclick=()=>{$('overlay').classList.remove('open');selectedJob=null};document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{if(!selectedJob){$('receipt').textContent='Select an active job before creating an action.';return}if(govMode!=='ON'){$('receipt').textContent='Governance is off. Turn governance on to create a governed action receipt.';return}let action=b.dataset.action;$('receipt').innerHTML='<b>SYNTHETIC ACTION RECEIPT</b><br>Branch: '+esc(currentBranch)+'<br>Job: '+esc(selectedJob.id)+'<br>Condition: '+esc((govResults[selectedJob.id]?.findings||[])[0]||govResults[selectedJob.id]?.label||'Governance review')+'<br>Action: '+esc(action.replaceAll('_',' '))+'<br>Next expectation: required evidence/state must be established at the next governance check.<br><span class="muted">Demo receipt only · no external message or task sent.</span>'});
Promise.all(['./september-2026-ledger-v1.json','./october-2026-forward-plan-v1.json','./annual-history-v1.json','./governance-feed-v1.json'].map(u=>fetch(u,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error(u+' '+r.status);return r.json()}))).then(([l,f,a,g])=>{ledger=l;forward=f;annual=a;govFeed=g;govResults=Object.fromEntries(g.jobs.map(x=>[x.jobId,GovernanceAdapter.qualifyJob(x)]));cycleQualification=GovernanceAdapter.qualifyCycle(g.agileCycle);applyMode();renderBridge()}).catch(e=>{$('flags').innerHTML='<p class="CRITICAL">Operating ledgers failed to load.</p>';console.error(e)})})();